import type { Course } from '../types'

export const COURSE: Course = {
  id: 'zh-hsk2-exchanges',
  language: 'zh',
  level: 'hsk2',
  entries: [
  { id: "h2x001", script: "你好！｜你好！你今天忙吗？｜不忙，我很高兴。", reading: "Nǐ hǎo! | Nǐ hǎo! Nǐ jīn tiān máng ma? | Bù máng, wǒ hěn gāo xìng.", english: "Hello! | Hello! Are you busy today? | Not busy, I'm very happy.", spanish: "¡Hola! | ¡Hola! ¿Estás ocupado hoy? | No estoy ocupado, estoy muy contento.", tags: ["exchange", "greet"] },
  { id: "h2x002", script: "你好吗？｜我很好，你呢？｜我也很好。", reading: "Nǐ hǎo ma? | Wǒ hěn hǎo, nǐ ne? | Wǒ yě hěn hǎo.", english: "How are you? | I'm well, and you? | I'm well too.", spanish: "¿Cómo estás? | Estoy muy bien, ¿y tú? | Yo también estoy muy bien.", tags: ["exchange", "greet"] },
  { id: "h2x003", script: "你是新同学吗？欢迎你！｜谢谢！我们做朋友吧！", reading: "Nǐ shì xīn tóng xué ma? Huān yíng nǐ! | Xiè xie! Wǒ men zuò péng you ba!", english: "Are you the new student? Welcome! | Thanks! Let's be friends!", spanish: "¿Eres el nuevo compañero? ¡Bienvenido! | ¡Gracias! ¡Seamos amigos!", tags: ["exchange", "greet"] },
  { id: "h2x004", script: "你好，你姓什么？｜我姓高，你呢？｜我姓白。", reading: "Nǐ hǎo, nǐ xìng shén me? | Wǒ xìng gāo, nǐ ne? | Wǒ xìng bái.", english: "Hello, what's your surname? | My surname is Gao, and yours? | My surname is Bai.", spanish: "Hola, ¿cuál es tu apellido? | Mi apellido es Gao, ¿y el tuyo? | Mi apellido es Bai.", tags: ["exchange", "greet"] },
  { id: "h2x005", script: "你今天很高兴，为什么？｜因为今天是我的生日！", reading: "Nǐ jīn tiān hěn gāo xìng, wèi shén me? | Yīn wèi jīn tiān shì wǒ de shēng rì!", english: "You're very happy today, why? | Because today is my birthday!", spanish: "Hoy estás muy contento, ¿por qué? | ¡Porque hoy es mi cumpleaños!", tags: ["exchange", "greet"] },
  { id: "h2x006", script: "我们明天一起玩，好吗？｜好，太好了！", reading: "Wǒ men míng tiān yì qǐ wán, hǎo ma? | Hǎo, tài hǎo le!", english: "Let's play together tomorrow, okay? | Great, sounds good!", spanish: "¿Jugamos juntos mañana, está bien? | ¡Sí, qué bueno!", tags: ["exchange", "greet"] },
  { id: "h2x008", script: "早上好！｜早上好！你几点起床的？｜我七点起床。", reading: "Zǎo shang hǎo! | Zǎo shang hǎo! Nǐ jǐ diǎn qǐ chuáng de? | Wǒ qī diǎn qǐ chuáng.", english: "Good morning! | Good morning! What time did you get up? | I got up at seven.", spanish: "¡Buenos días! | ¡Buenos días! ¿A qué hora te levantaste? | Me levanté a las siete.", tags: ["exchange", "greet"] },
  { id: "h2x009", script: "你好，你今天要去哪儿？｜我要去学校，你呢？｜我要去商店。", reading: "Nǐ hǎo, nǐ jīn tiān yào qù nǎr? | Wǒ yào qù xué xiào, nǐ ne? | Wǒ yào qù shāng diàn.", english: "Hello, where are you going today? | I'm going to school, and you? | I'm going to the store.", spanish: "Hola, ¿adónde vas hoy? | Voy a la escuela, ¿y tú? | Voy a la tienda.", tags: ["exchange", "greet"] },
  { id: "h2x010", script: "你好！你今天想做什么？｜我想去游泳，你呢？｜我想休息。", reading: "Nǐ hǎo! Nǐ jīn tiān xiǎng zuò shén me? | Wǒ xiǎng qù yóu yǒng, nǐ ne? | Wǒ xiǎng xiū xi.", english: "Hello! What do you want to do today? | I want to go swimming, and you? | I want to rest.", spanish: "¡Hola! ¿Qué quieres hacer hoy? | Quiero ir a nadar, ¿y tú? | Quiero descansar.", tags: ["exchange", "greet"] },
  { id: "h2x011", script: "你想吃什么？｜我想吃面条，你呢？｜我想吃鸡蛋。", reading: "Nǐ xiǎng chī shén me? | Wǒ xiǎng chī miàn tiáo, nǐ ne? | Wǒ xiǎng chī jī dàn.", english: "What do you want to eat? | I want to eat noodles, and you? | I want to eat eggs.", spanish: "¿Qué quieres comer? | Quiero comer fideos, ¿y tú? | Quiero comer huevos.", tags: ["exchange", "food"] },
  { id: "h2x012", script: "这个面条好吃吗？｜非常好吃！你也吃一点儿吧。", reading: "Zhè ge miàn tiáo hǎo chī ma? | Fēi cháng hǎo chī! Nǐ yě chī yì diǎnr ba.", english: "Are these noodles tasty? | Very tasty! You have some too.", spanish: "¿Están ricos estos fideos? | ¡Están riquísimos! Come un poco también.", tags: ["exchange", "food"] },
  { id: "h2x013", script: "你想喝咖啡还是牛奶？｜我想喝咖啡，谢谢。", reading: "Nǐ xiǎng hē kā fēi hái shì niú nǎi? | Wǒ xiǎng hē kā fēi, xiè xie.", english: "Do you want coffee or milk? | I'd like coffee, thanks.", spanish: "¿Quieres tomar café o leche? | Quiero café, gracias.", tags: ["exchange", "food"] },
  { id: "h2x014", script: "你觉得这个西瓜怎么样？｜很好吃，我很喜欢。", reading: "Nǐ jué de zhè ge xī guā zěn me yàng? | Hěn hǎo chī, wǒ hěn xǐ huan.", english: "What do you think of this watermelon? | It's tasty, I like it a lot.", spanish: "¿Qué te parece esta sandía? | Está muy rica, me encanta.", tags: ["exchange", "food"] },
  { id: "h2x015", script: "服务员，我要一个鸡蛋面。｜好的，请等一下。", reading: "Fú wù yuán, wǒ yào yí gè jī dàn miàn. | Hǎo de, qǐng děng yí xià.", english: "Waiter, I'd like an egg noodle dish. | Sure, please wait a moment.", spanish: "Mesero, quiero unos fideos con huevo. | Claro, espera un momento.", tags: ["exchange", "food"] },
  { id: "h2x016", script: "这个多少钱？｜很便宜，三块钱。｜太好了，我买一个。", reading: "Zhè ge duō shao qián? | Hěn pián yi, sān kuài qián. | Tài hǎo le, wǒ mǎi yí gè.", english: "How much is this? | It's cheap, three yuan. | Great, I'll buy one.", spanish: "¿Cuánto cuesta esto? | Es muy barato, tres yuanes. | ¡Qué bien, compro uno!", tags: ["exchange", "food"] },
  { id: "h2x017", script: "这个苹果很贵。｜是的，但是很好吃。", reading: "Zhè ge píng guǒ hěn guì. | Shì de, dàn shì hěn hǎo chī.", english: "This apple is quite expensive. | Yeah, but it's very tasty.", spanish: "Esta manzana es muy cara. | Sí, pero está muy rica.", tags: ["exchange", "food"] },
  { id: "h2x018", script: "你在准备晚饭吗？｜是，我在做鸡蛋面。", reading: "Nǐ zài zhǔn bèi wǎn fàn ma? | Shì, wǒ zài zuò jī dàn miàn.", english: "Are you preparing dinner? | Yes, I'm making egg noodles.", spanish: "¿Estás preparando la cena? | Sí, estoy haciendo fideos con huevo.", tags: ["exchange", "food"] },
  { id: "h2x019", script: "你已经吃饭了吗？｜还没有，我想现在吃。", reading: "Nǐ yǐ jīng chī fàn le ma? | Hái méi yǒu, wǒ xiǎng xiàn zài chī.", english: "Have you already eaten? | Not yet, I want to eat now.", spanish: "¿Ya comiste? | Todavía no, quiero comer ahora.", tags: ["exchange", "food"] },
  { id: "h2x020", script: "我们一起去饭店吃饭吧！｜好，我也想吃鱼。", reading: "Wǒ men yì qǐ qù fàn diàn chī fàn ba! | Hǎo, wǒ yě xiǎng chī yú.", english: "Let's go eat at a restaurant together! | Sure, I want to eat fish too.", spanish: "¡Vamos a comer juntos a un restaurante! | Bien, yo también quiero comer pescado.", tags: ["exchange", "food"] },
  { id: "h2x021", script: "你吃过羊肉吗？｜吃过，很好吃，但是有点儿贵。", reading: "Nǐ chī guo yáng ròu ma? | Chī guo, hěn hǎo chī, dàn shì yǒu diǎnr guì.", english: "Have you had mutton before? | Yes, it's tasty, but a bit expensive.", spanish: "¿Has comido carne de cordero? | Sí, es muy rica, pero es un poco cara.", tags: ["exchange", "food"] },
  { id: "h2x022", script: "你觉得咖啡好喝吗？｜好喝，我很喜欢咖啡。", reading: "Nǐ jué de kā fēi hǎo hē ma? | Hǎo hē, wǒ hěn xǐ huan kā fēi.", english: "Do you think coffee tastes good? | It does, I really like coffee.", spanish: "¿Crees que el café está rico? | Sí, está rico, me gusta mucho el café.", tags: ["exchange", "food"] },
  { id: "h2x024", script: "明天会下雪吗？｜可能会，天气很冷。", reading: "Míng tiān huì xià xuě ma? | Kě néng huì, tiān qì hěn lěng.", english: "Will it snow tomorrow? | Maybe, it's very cold.", spanish: "¿Nevará mañana? | Puede que sí, hace mucho frío.", tags: ["exchange", "weather"] },
  { id: "h2x025", script: "今天是晴天还是阴天？｜是阴天，可能要下雨。", reading: "Jīn tiān shì qíng tiān hái shì yīn tiān? | Shì yīn tiān, kě néng yào xià yǔ.", english: "Is it sunny or cloudy today? | It's cloudy, it might rain.", spanish: "¿Hoy está soleado o nublado? | Está nublado, puede que llueva.", tags: ["exchange", "weather"] },
  { id: "h2x026", script: "外面在下雪！｜真的吗？我们出去玩吧！", reading: "Wài mian zài xià xuě! | Zhēn de ma? Wǒ men chū qù wán ba!", english: "It's snowing outside! | Really? Let's go out and play!", spanish: "¡Está nevando afuera! | ¿De verdad? ¡Vamos a jugar afuera!", tags: ["exchange", "weather"] },
  { id: "h2x027", script: "今天非常热，你热吗？｜我也很热，想去游泳。", reading: "Jīn tiān fēi cháng rè, nǐ rè ma? | Wǒ yě hěn rè, xiǎng qù yóu yǒng.", english: "It's extremely hot today, are you hot? | I'm hot too, I want to go swimming.", spanish: "Hoy hace mucho calor, ¿tienes calor? | Yo también tengo calor, quiero ir a nadar.", tags: ["exchange", "weather"] },
  { id: "h2x028", script: "现在天气怎么样？｜现在很冷，但是明天会晴。", reading: "Xiàn zài tiān qì zěn me yàng? | Xiàn zài hěn lěng, dàn shì míng tiān huì qíng.", english: "What's the weather like now? | It's cold now, but tomorrow will be sunny.", spanish: "¿Cómo está el clima ahora? | Ahora hace frío, pero mañana estará soleado.", tags: ["exchange", "weather"] },
  { id: "h2x029", script: "下雨了，我们回家吧。｜好，我们等一下再走。", reading: "Xià yǔ le, wǒ men huí jiā ba. | Hǎo, wǒ men děng yí xià zài zǒu.", english: "It's raining, let's go home. | Okay, let's wait a bit and then go.", spanish: "Está lloviendo, vamos a casa. | Bien, esperemos un poco y luego nos vamos.", tags: ["exchange", "weather"] },
  { id: "h2x030", script: "今天天气真好！｜是的，我们一起去外面玩吧。", reading: "Jīn tiān tiān qì zhēn hǎo! | Shì de, wǒ men yì qǐ qù wài mian wán ba.", english: "The weather's really nice today! | Yeah, let's go outside and play together.", spanish: "¡Qué buen clima hace hoy! | Sí, vamos a jugar afuera juntos.", tags: ["exchange", "weather"] },
  { id: "h2x031", script: "你几点睡觉？｜我晚上十点睡觉，你呢？｜我十一点睡觉。", reading: "Nǐ jǐ diǎn shuì jiào? | Wǒ wǎn shang shí diǎn shuì jiào, nǐ ne? | Wǒ shí yī diǎn shuì jiào.", english: "What time do you go to sleep? | I go to sleep at ten in the evening, and you? | I go to sleep at eleven.", spanish: "¿A qué hora te duermes? | Me duermo a las diez de la noche, ¿y tú? | Yo me duermo a las once.", tags: ["exchange", "sleep"] },
  { id: "h2x032", script: "你今天很累吗？｜非常累，我想早点休息。", reading: "Nǐ jīn tiān hěn lèi ma? | Fēi cháng lèi, wǒ xiǎng zǎo diǎn xiū xi.", english: "Are you very tired today? | Extremely tired, I want to rest a bit early.", spanish: "¿Estás muy cansado hoy? | Muy cansado, quiero descansar temprano.", tags: ["exchange", "sleep"] },
  { id: "h2x033", script: "你几点起床？｜我早上七点起床。", reading: "Nǐ jǐ diǎn qǐ chuáng? | Wǒ zǎo shang qī diǎn qǐ chuáng.", english: "What time do you get up? | I get up at seven in the morning.", spanish: "¿A qué hora te levantas? | Me levanto a las siete de la mañana.", tags: ["exchange", "sleep"] },
  { id: "h2x034", script: "你昨天晚上睡得好吗？｜睡得很好，我现在不累。", reading: "Nǐ zuó tiān wǎn shang shuì de hǎo ma? | Shuì de hěn hǎo, wǒ xiàn zài bú lèi.", english: "Did you sleep well last night? | I slept really well, I'm not tired now.", spanish: "¿Dormiste bien anoche? | Dormí muy bien, ahora no estoy cansado.", tags: ["exchange", "sleep"] },
  { id: "h2x035", script: "你昨天睡了几个小时？｜我睡了八个小时。", reading: "Nǐ zuó tiān shuì le jǐ gè xiǎo shí? | Wǒ shuì le bā gè xiǎo shí.", english: "How many hours did you sleep yesterday? | I slept for eight hours.", spanish: "¿Cuántas horas dormiste ayer? | Dormí ocho horas.", tags: ["exchange", "sleep"] },
  { id: "h2x036", script: "你有哥哥吗？｜没有，但是我有一个弟弟和一个妹妹。", reading: "Nǐ yǒu gē ge ma? | Méi yǒu, dàn shì wǒ yǒu yí gè dì di hé yí gè mèi mei.", english: "Do you have an older brother? | No, but I have a younger brother and a younger sister.", spanish: "¿Tienes hermano mayor? | No, pero tengo un hermano menor y una hermana menor.", tags: ["exchange", "random"] },
  { id: "h2x037", script: "你姐姐做什么工作？｜她在一家公司上班。", reading: "Nǐ jiě jie zuò shén me gōng zuò? | Tā zài yì jiā gōng sī shàng bān.", english: "What does your older sister do for work? | She works at a company.", spanish: "¿En qué trabaja tu hermana mayor? | Trabaja en una empresa.", tags: ["exchange", "random"] },
  { id: "h2x038", script: "你喜欢什么运动？｜我喜欢踢足球，你呢？｜我喜欢打篮球。", reading: "Nǐ xǐ huan shén me yùn dòng? | Wǒ xǐ huan tī zú qiú, nǐ ne? | Wǒ xǐ huan dǎ lán qiú.", english: "What sport do you like? | I like playing football, and you? | I like playing basketball.", spanish: "¿Qué deporte te gusta? | Me gusta jugar fútbol, ¿y a ti? | Me gusta jugar básquetbol.", tags: ["exchange", "random"] },
  { id: "h2x039", script: "你每天跑步吗？｜是，我每天跑步，身体很好。", reading: "Nǐ měi tiān pǎo bù ma? | Shì, wǒ měi tiān pǎo bù, shēn tǐ hěn hǎo.", english: "Do you jog every day? | Yes, I jog every day, I'm very healthy.", spanish: "¿Corres todos los días? | Sí, corro todos los días, estoy muy sano.", tags: ["exchange", "random"] },
  { id: "h2x040", script: "明天有考试吗？｜有，是汉语考试，我有点儿忙。", reading: "Míng tiān yǒu kǎo shì ma? | Yǒu, shì hàn yǔ kǎo shì, wǒ yǒu diǎnr máng.", english: "Is there an exam tomorrow? | Yes, a Chinese exam, I'm a bit busy.", spanish: "¿Hay examen mañana? | Sí, es de chino, estoy un poco ocupado.", tags: ["exchange", "random"] },
  { id: "h2x041", script: "这个问题你懂吗？｜不懂，你可以告诉我吗？｜可以，我来帮助你。", reading: "Zhè ge wèn tí nǐ dǒng ma? | Bù dǒng, nǐ kě yǐ gào su wǒ ma? | Kě yǐ, wǒ lái bāng zhù nǐ.", english: "Do you understand this problem? | I don't, can you tell me? | Sure, I'll help you.", spanish: "¿Entiendes esta pregunta? | No, ¿puedes decirme? | Claro, te ayudo.", tags: ["exchange", "random"] },
  { id: "h2x042", script: "老师问了一个问题，你回答了吗？｜回答了，但是我觉得我错了。", reading: "Lǎo shī wèn le yí gè wèn tí, nǐ huí dá le ma? | Huí dá le, dàn shì wǒ jué de wǒ cuò le.", english: "The teacher asked a question, did you answer it? | I did, but I think I got it wrong.", spanish: "La maestra hizo una pregunta, ¿la respondiste? | Sí, pero creo que me equivoqué.", tags: ["exchange", "random"] },
  { id: "h2x043", script: "你的手机在哪儿？｜在桌子上边。", reading: "Nǐ de shǒu jī zài nǎr? | Zài zhuō zi shàng bian.", english: "Where's your phone? | It's on the table.", spanish: "¿Dónde está tu celular? | Está sobre la mesa.", tags: ["exchange", "random"] },
  { id: "h2x044", script: "宾馆在哪儿？离这儿远吗？｜不远，很近，在你的右边。", reading: "Bīn guǎn zài nǎr? Lí zhèr yuǎn ma? | Bù yuǎn, hěn jìn, zài nǐ de yòu bian.", english: "Where's the hotel? Is it far from here? | Not far, it's close, on your right.", spanish: "¿Dónde está el hotel? ¿Está lejos de aquí? | No está lejos, está cerca, a tu derecha.", tags: ["exchange", "random"] },
  { id: "h2x045", script: "机场怎么走？｜往前走，机场就在左边。", reading: "Jī chǎng zěn me zǒu? | Wǎng qián zǒu, jī chǎng jiù zài zuǒ bian.", english: "How do I get to the airport? | Go straight ahead, the airport is right on the left.", spanish: "¿Cómo se llega al aeropuerto? | Sigue derecho, el aeropuerto está a la izquierda.", tags: ["exchange", "random"] },
  { id: "h2x046", script: "这件衣服多少钱？｜不贵，很便宜。｜太好了，我买了。", reading: "Zhè jiàn yī fu duō shao qián? | Bú guì, hěn pián yi. | Tài hǎo le, wǒ mǎi le.", english: "How much is this piece of clothing? | Not expensive, it's cheap. | Great, I'll buy it.", spanish: "¿Cuánto cuesta esta ropa? | No es cara, es muy barata. | ¡Qué bien, la compro!", tags: ["exchange", "random"] },
  { id: "h2x047", script: "你想买铅笔吗？｜想，我也要买报纸。", reading: "Nǐ xiǎng mǎi qiān bǐ ma? | Xiǎng, wǒ yě yào mǎi bào zhǐ.", english: "Do you want to buy a pencil? | Yes, I also want to buy a newspaper.", spanish: "¿Quieres comprar un lápiz? | Sí, también quiero comprar un periódico.", tags: ["exchange", "random"] },
  { id: "h2x048", script: "你去年去哪儿旅游了？｜我去年去了北京，非常漂亮。", reading: "Nǐ qù nián qù nǎr lǚ yóu le? | Wǒ qù nián qù le běi jīng, fēi cháng piào liang.", english: "Where did you travel last year? | I went to Beijing last year, it's very beautiful.", spanish: "¿Adónde viajaste el año pasado? | Fui a Beijing el año pasado, es muy hermosa.", tags: ["exchange", "random"] },
  { id: "h2x049", script: "飞机快到机场了吗？｜快到了，我们准备下飞机吧。", reading: "Fēi jī kuài dào jī chǎng le ma? | Kuài dào le, wǒ men zhǔn bèi xià fēi jī ba.", english: "Is the plane about to reach the airport? | Almost there, let's get ready to get off.", spanish: "¿El avión ya casi llega al aeropuerto? | Ya casi llegamos, preparémonos para bajar.", tags: ["exchange", "random"] },
  { id: "h2x050", script: "你最喜欢什么颜色？｜我最喜欢红色，你呢？｜我喜欢黑色。", reading: "Nǐ zuì xǐ huan shén me yán sè? | Wǒ zuì xǐ huan hóng sè, nǐ ne? | Wǒ xǐ huan hēi sè.", english: "What's your favorite color? | I like red the most, and you? | I like black.", spanish: "¿Cuál es tu color favorito? | Mi favorito es el rojo, ¿y el tuyo? | Me gusta el negro.", tags: ["exchange", "random"] },
  { id: "h2x051", script: "你今天为什么不快乐？｜因为我的手表不见了。", reading: "Nǐ jīn tiān wèi shén me bú kuài lè? | Yīn wèi wǒ de shǒu biǎo bú jiàn le.", english: "Why aren't you happy today? | Because my watch is missing.", spanish: "¿Por qué no estás feliz hoy? | Porque se me perdió el reloj.", tags: ["exchange", "random"] },
  { id: "h2x052", script: "你笑什么？｜我觉得今天很快乐。", reading: "Nǐ xiào shén me? | Wǒ jué de jīn tiān hěn kuài lè.", english: "What are you smiling about? | I just feel happy today.", spanish: "¿De qué te ríes? | Es que hoy me siento muy feliz.", tags: ["exchange", "random"] },
  { id: "h2x053", script: "你怎么了？｜我可能生病了，身体不太好。", reading: "Nǐ zěn me le? | Wǒ kě néng shēng bìng le, shēn tǐ bú tài hǎo.", english: "What's wrong? | I might be sick, I'm not feeling well.", spanish: "¿Qué te pasa? | Creo que estoy enfermo, no me siento muy bien.", tags: ["exchange", "random"] },
  { id: "h2x054", script: "你要去医院吗？｜要，我想买一点儿药。", reading: "Nǐ yào qù yī yuàn ma? | Yào, wǒ xiǎng mǎi yì diǎnr yào.", english: "Are you going to the hospital? | Yes, I want to buy some medicine.", spanish: "¿Vas a ir al hospital? | Sí, quiero comprar un poco de medicina.", tags: ["exchange", "random"] },
  { id: "h2x055", script: "你会跳舞吗？｜会一点儿，我也喜欢唱歌。", reading: "Nǐ huì tiào wǔ ma? | Huì yì diǎnr, wǒ yě xǐ huan chàng gē.", english: "Can you dance? | A little, I also like singing.", spanish: "¿Sabes bailar? | Un poco, también me gusta cantar.", tags: ["exchange", "random"] },
  { id: "h2x056", script: "公共汽车什么时候到？｜可能五分钟就到。", reading: "Gōng gòng qì chē shén me shí hou dào? | Kě néng wǔ fēn zhōng jiù dào.", english: "When will the bus arrive? | It'll probably arrive in five minutes.", spanish: "¿Cuándo llega el autobús? | Probablemente llegue en cinco minutos.", tags: ["exchange", "random"] },
  { id: "h2x057", script: "他是你的丈夫吗？｜是，我们已经认识十年了。", reading: "Tā shì nǐ de zhàng fu ma? | Shì, wǒ men yǐ jīng rèn shi shí nián le.", english: "Is he your husband? | Yes, we've known each other for ten years already.", spanish: "¿Él es tu esposo? | Sí, ya nos conocemos desde hace diez años.", tags: ["exchange", "random"] },
  { id: "h2x058", script: "她是你的妻子吗？｜是，她是一个很好的老师。", reading: "Tā shì nǐ de qī zi ma? | Shì, tā shì yí gè hěn hǎo de lǎo shī.", english: "Is she your wife? | Yes, she's a very good teacher.", spanish: "¿Ella es tu esposa? | Sí, es una muy buena maestra.", tags: ["exchange", "random"] },
  { id: "h2x059", script: "你在找什么？｜我在找我的手机，你看见了吗？｜没看见。", reading: "Nǐ zài zhǎo shén me? | Wǒ zài zhǎo wǒ de shǒu jī, nǐ kàn jiàn le ma? | Méi kàn jiàn.", english: "What are you looking for? | I'm looking for my phone, have you seen it? | No, I haven't.", spanish: "¿Qué estás buscando? | Estoy buscando mi celular, ¿lo has visto? | No lo he visto.", tags: ["exchange", "random"] },
  { id: "h2x060", script: "你正在做什么？｜我正在洗衣服，你呢？｜我在看报纸。", reading: "Nǐ zhèng zài zuò shén me? | Wǒ zhèng zài xǐ yī fu, nǐ ne? | Wǒ zài kàn bào zhǐ.", english: "What are you doing right now? | I'm washing clothes, and you? | I'm reading the newspaper.", spanish: "¿Qué estás haciendo? | Estoy lavando ropa, ¿y tú? | Estoy leyendo el periódico.", tags: ["exchange", "random"] },
  ],
}
